SITE_ASSET_VERSION = open(os.path.join(ROOT, "SITE-ASSET-VERSION"), "r", encoding="utf-8").read().strip()


def _normalize_site_asset_marker(value):
    value = re.sub(r"script\.js\?v=[A-Za-z0-9_-]+", f"script.js?v={SITE_ASSET_VERSION}", value)
    value = re.sub(r"styles\.css\?v=[A-Za-z0-9_-]+", f"styles.css?v={SITE_ASSET_VERSION}", value)
    value = re.sub(r"tt-bootstrap\.js\?v=[A-Za-z0-9_-]+", f"tt-bootstrap.js?v={SITE_ASSET_VERSION}", value)
    value = re.sub(r"footer-build-stamp\.js\?v=[A-Za-z0-9_-]+", f"footer-build-stamp.js?v={SITE_ASSET_VERSION}", value)
    value = re.sub(r"share-page\.js\?v=[A-Za-z0-9_-]+", f"share-page.js?v={SITE_ASSET_VERSION}", value)
    value = re.sub(r"language-switcher\.js\?v=[A-Za-z0-9_-]+", f"language-switcher.js?v={SITE_ASSET_VERSION}", value)
    return value

